INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'What is the central economic problem?', 'Scarcity: human wants are unlimited but the resources (factors of production) available to satisfy them are finite, so choices must be made about what to produce, how, and for whom.', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'List the four factors of production with their respective rewards.', 'Land (rent), labour (wages), capital (interest), enterprise (profit). Enterprise organises the other three and bears risk.', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Define opportunity cost.', 'The value of the next-best alternative forgone when a choice is made. It applies to consumers, firms and governments.', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'What does a Production Possibility Frontier (PPF) show?', 'The maximum combinations of two goods an economy can produce when all resources are fully and efficiently employed, given the current state of technology. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 25 Q70 32 130 75 T200 130" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Good X</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">Good Y</text><text x="135" y="105" font-size="9" fill="#0B1E3F">PPF</text></svg>', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'What does a point inside the PPF indicate?', 'Productive inefficiency or unemployed/underused resources — output could be increased without sacrificing any other good.', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Why is a PPF typically concave to the origin?', 'Because resources are not equally productive in all uses; reallocating them yields increasing opportunity costs as factors better suited to the other good must eventually be transferred.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Distinguish economic growth from economic development.', 'Growth = rise in real GDP (quantitative). Development = broader improvement in living standards including health, education, equality and political freedom (qualitative).', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Distinguish positive and normative statements.', 'Positive statements describe what is and can be tested against evidence. Normative statements involve value judgements about what ought to be and cannot be empirically verified.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'What is the difference between a free market, command and mixed economy?', 'Free market: resources allocated by price signals and private ownership. Command: state plans and owns resources. Mixed: combines private market with public-sector provision and regulation — most real economies.',9, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'State Adam Smith''s ''invisible hand'' idea.', 'Self-interested individuals trading in competitive markets are guided as if by an invisible hand to allocate resources efficiently and benefit society.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Define specialisation and the division of labour.', 'Specialisation: workers/firms/countries focus on the tasks they are best at. Division of labour: breaking production into specialised tasks performed by different workers, raising productivity (Smith''s pin factory).', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Give two advantages and one disadvantage of the division of labour.', 'Advantages: higher productivity from practice; lower training costs per task; faster output. Disadvantage: monotony lowers worker morale, raising turnover and absenteeism.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'What three functions does money perform?', 'Medium of exchange (replaces barter), store of value (purchasing power preserved over time), unit of account (common measure of value). Some texts add ''standard of deferred payment''.', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Why does an outward shift of the PPF represent economic growth?', 'It signals that potential output has risen — through more or better factors of production (investment, education, immigration) or improved technology — so previously unattainable combinations are now feasible.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'What is the ceteris paribus assumption?', 'Latin for ''other things equal'' — economists isolate the effect of one variable by holding all others constant, an essential simplifying assumption when building models.', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.1', 'The Economic Problem and Methodology', 'Why are economic models simplifications?', 'Because the real economy contains millions of agents and variables; models abstract from detail to identify causal relationships and make predictions, accepting some loss of realism.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Define utility and state the consumer objective assumed by economic theory.', 'Utility is the satisfaction or benefit derived from consuming a good or service. The traditional model assumes the consumer''s objective is utility maximisation: getting the greatest possible satisfaction from a limited budget.', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Distinguish total utility from marginal utility and state how they are related.', 'Total utility (TU) is the overall satisfaction from consuming a given quantity; marginal utility (MU) is the addition to TU from one more unit, so MU = change in TU / change in Q. TU rises at a decreasing rate while MU is positive but falling, peaks where MU = 0, and falls once MU is negative. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="25" y1="140" x2="25" y2="15" stroke="#0B1E3F"/><line x1="25" y1="100" x2="210" y2="100" stroke="#0B1E3F"/><path d="M25 100 Q82 25 140 25 Q172 25 200 45" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="25" y1="60" x2="200" y2="121" stroke="#0B1E3F" stroke-width="1.5" stroke-dasharray="3,2"/><line x1="140" y1="25" x2="140" y2="121" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><text x="203" y="46" font-size="9" fill="#0B1E3F">TU</text><text x="203" y="126" font-size="9" fill="#0B1E3F">MU</text><text x="140" y="114" font-size="8" fill="#0B1E3F" text-anchor="middle">Q*</text><text x="208" y="112" font-size="8" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'State the law of diminishing marginal utility and its two conditions.', 'As successive units of a good are consumed, the additional satisfaction from each extra unit eventually falls. Conditions: it applies within a given time period, and ceteris paribus (tastes, income and consumption of other goods held constant).', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'At what quantity is total utility maximised, and what happens beyond it?', 'Total utility is maximised at the satiation point, where marginal utility equals zero. Beyond it marginal utility is negative, so each further unit reduces total utility. A common error is to say diminishing MU makes TU fall — it only makes TU rise more slowly.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'How does diminishing marginal utility explain the downward-sloping demand curve?', 'A rational consumer buys an extra unit only while its marginal utility is at least equal to the price paid, so MU of the last unit = P. Since MU falls as quantity rises, a lower price is needed to make later units worth buying — the MU curve in money terms is the individual demand curve. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="25" y1="130" x2="25" y2="15" stroke="#0B1E3F"/><line x1="25" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="40" y1="25" x2="185" y2="120" stroke="#0B1E3F" stroke-width="1.5"/><line x1="25" y1="50" x2="78" y2="50" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><line x1="78" y1="50" x2="78" y2="130" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><line x1="25" y1="95" x2="147" y2="95" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><line x1="147" y1="95" x2="147" y2="130" stroke="#0B1E3F" stroke-width="0.7" stroke-dasharray="2,2"/><text x="22" y="53" font-size="8" fill="#0B1E3F" text-anchor="end">P1</text><text x="22" y="98" font-size="8" fill="#0B1E3F" text-anchor="end">P2</text><text x="78" y="142" font-size="8" fill="#0B1E3F" text-anchor="middle">Q1</text><text x="147" y="142" font-size="8" fill="#0B1E3F" text-anchor="middle">Q2</text><text x="188" y="122" font-size="8" fill="#0B1E3F">MU=D</text></svg>', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'State the equi-marginal principle and define consumer equilibrium.', 'A utility-maximising consumer allocates income so that the marginal utility of the last pound spent is equal on every good: MUa/Pa = MUb/Pb = ... = MUn/Pn. Consumer equilibrium is that point — no reallocation of a pound between goods can raise total utility. Note the price in the denominator.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'List the four assumptions of the traditional model of rational economic decision making.', 'Utility (or profit) maximisation; perfect information about all options, prices and outcomes; transitive and consistent preferences; pure self-interest. Two further conditions are often added: unlimited cognitive capacity and unlimited willpower.', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Distinguish imperfect information from asymmetric information.', 'Imperfect information means agents lack the complete or accurate information needed to maximise welfare (gaps or inaccuracy). Asymmetric information is the special case where one party to a transaction knows more than the other and can exploit that advantage.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Name two consequences of asymmetric information in insurance markets.', 'Adverse selection: before the contract, high-risk customers are keenest to buy cover, raising premiums and driving out low-risk buyers. Moral hazard: after the contract, being insured makes risky behaviour more likely. Akerlof''s ''market for lemons'' (1970) makes the same point for used cars.', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'What is bounded rationality?', 'Herbert Simon''s idea that agents intend to be rational but are limited by the information they have, their cognitive capacity and the time available. Rather than optimising they satisfice — accepting the first option that is good enough — often by using heuristics.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'What is bounded self-control, and why is it damaging to the traditional model?', 'Agents know what is in their long-term interest but lack the willpower to act on it (unused gym memberships, abandoned saving plans). It is damaging because the agent has full information and a clear objective and still fails to maximise utility.', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Define anchoring, availability bias and herding.', 'Anchoring: over-weighting the first piece of information seen (a ''was £120, now £60'' sticker). Availability bias: judging probability by how easily examples come to mind (over-rating air crash risk after news coverage). Herding: copying the group, e.g. panic buying of fuel.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Define loss aversion and the endowment effect.', 'Loss aversion (Kahneman and Tversky''s prospect theory, 1979): losses are felt roughly twice as strongly as equivalent gains, judged from a reference point rather than total wealth. The endowment effect follows: owning a good raises its value, so the selling price demanded exceeds the buying price offered.', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Define framing and present bias (hyperbolic discounting).', 'Framing: the same choice produces different decisions depending on presentation (''90% fat free'' outsells ''contains 10% fat''), which contradicts consistent preferences. Present bias: heavily over-weighting immediate costs and benefits, reversing earlier plans — e.g. taking a high-APR payday loan.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Define choice architecture and a nudge, and name the main policy tools.', 'Choice architecture is the design of the environment in which decisions are made. A nudge alters behaviour predictably without banning options or significantly changing incentives (Thaler and Sunstein''s ''Nudge'', 2008 — ''libertarian paternalism''). Tools: default choice, framing, salience, restricted choice, mandated choice. The Behavioural Insights Team was set up in the Cabinet Office in 2010.', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.2', 'Individual Economic Decision Making', 'Give two UK examples of behavioural policy and one evaluation point on nudges.', 'Auto-enrolment (phased in from 2012) moved eligible-employee pension participation from roughly 55% in 2012 to over 88% by 2024; England adopted opt-out organ donation in May 2020 under Max and Keira''s Law. Evaluation: nudges are very cheap and preserve choice, but effects can be modest and fade, so for large externalities they complement rather than replace taxes and regulation.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'State the law of demand.', 'Ceteris paribus, as price falls, quantity demanded rises (and vice versa). Demand curves slope downwards because of the income effect, the substitution effect and diminishing marginal utility.', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Distinguish a movement along a demand curve from a shift of it.', 'A movement (extension/contraction) is caused by a change in the good''s own price. A shift is caused by a change in any other determinant (income, related-good prices, tastes, expectations, population).', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'What is consumer surplus?', 'The difference between the maximum price consumers are willing to pay and the price they actually pay — represented by the area below the demand curve and above the market price up to the equilibrium quantity.', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Define price elasticity of demand (PED) and give its formula.', 'PED measures the responsiveness of quantity demanded to a change in price. PED = % change in Qd / % change in P. It is normally negative; sign is conventionally ignored.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Name three determinants of PED.', 'Availability and closeness of substitutes; share of income spent on the good; necessity vs luxury; time period (more elastic in the long run); habit/addiction.', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Relate PED to total revenue.', 'If demand is price-elastic (|PED| > 1), a price cut raises total revenue. If inelastic (|PED| < 1), a price cut lowers total revenue. At unitary elasticity, revenue is maximised.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Define cross elasticity of demand (XED).', 'XED = % change in Qd of good A / % change in P of good B. Positive XED indicates substitutes (e.g. Coke and Pepsi); negative XED indicates complements (e.g. cars and petrol).', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Define income elasticity of demand (YED) and interpret its sign.', 'YED = % change in Qd / % change in income. Positive: normal good (luxury if YED>1, necessity if 0<YED<1). Negative: inferior good — demand falls as income rises.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'State the law of supply.', 'Ceteris paribus, as price rises, quantity supplied rises. Supply curves slope upwards because higher prices cover higher marginal costs and incentivise producers to expand output.', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Name three determinants that shift the supply curve.', 'Costs of production (wages, raw materials), technology, indirect taxes/subsidies, the number of firms, expectations and producer goals. A change in own price moves along the curve, not shifts it.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Define price elasticity of supply (PES).', 'PES = % change in Qs / % change in P. PES depends on spare capacity, ease of stockholding, factor mobility and the time horizon — supply is more elastic in the long run.', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'How is market equilibrium determined?', 'Where the demand and supply curves intersect — quantity demanded equals quantity supplied at the market-clearing price. Surplus pushes price down; shortage pushes it up. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="30" x2="195" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="125" x2="195" y2="30" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="78" x2="120" y2="78" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="120" y1="78" x2="120" y2="130" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><text x="198" y="125" font-size="9" fill="#0B1E3F">D</text><text x="198" y="30" font-size="9" fill="#0B1E3F">S</text><text x="28" y="81" font-size="9" fill="#0B1E3F" text-anchor="end">P*</text><text x="120" y="145" font-size="9" fill="#0B1E3F" text-anchor="middle">Q*</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'What does the price mechanism do? (Three functions)', 'Signalling (prices convey information about scarcity), incentive (high prices attract producers and ration consumers) and rationing (price rises so demand equals supply when goods are scarce).', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'What does producer surplus represent?', 'The difference between the price producers receive and the minimum they would be willing to accept — the area above the supply curve and below the market price.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'Explain joint demand and competitive demand with examples.', 'Joint (complements): goods bought together — printers and ink. Competitive (substitutes): goods bought as alternatives — butter and margarine. Joint supply: producing one good automatically yields another (beef and leather).', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.3', 'Price Determination in a Competitive Market', 'How does a sales tax (specific tax) affect equilibrium when demand is inelastic?', 'It shifts supply leftward by the tax. With inelastic demand, the consumer bears most of the burden (incidence) — price rises sharply, quantity falls a little, and tax revenue is large.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Distinguish production from productivity.', 'Production = total quantity of output produced. Productivity = output per unit of input (labour productivity = output per worker per hour). Productivity drives long-run living standards.', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'State the law of diminishing marginal returns.', 'In the short run, as more variable input is added to a fixed input, the marginal product of the variable input eventually falls. It causes the short-run MC curve to slope upward.', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Distinguish fixed and variable costs.', 'Fixed costs do not vary with output (rent, insurance, salaried staff). Variable costs change with output (raw materials, wages of hourly workers). FC + VC = TC.', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Define average cost and marginal cost.', 'AC = TC/Q (cost per unit). MC = ΔTC/ΔQ (cost of producing one more unit). MC cuts AC at its minimum because adding a unit cheaper than average pulls average down.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Why is the short-run AC curve U-shaped?', 'Initially, spreading fixed costs over more units lowers AFC and AC; eventually diminishing returns raise AVC and pull AC back up. The minimum is the productively efficient level of output. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 50 Q90 110 130 80 T200 35" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><path d="M40 90 Q100 120 140 95 T200 50" stroke="#0B1E3F" stroke-width="1.5" fill="none" stroke-dasharray="3 2"/><circle cx="125" cy="92" r="2.5" fill="#0B1E3F"/><text x="198" y="35" font-size="9" fill="#0B1E3F">MC</text><text x="198" y="55" font-size="9" fill="#0B1E3F">AC</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">£</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Define returns to scale.', 'Long-run response of output to a proportional change in all inputs. Increasing returns: output rises more than proportionally. Constant: same proportion. Decreasing: less than proportional.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'List four internal economies of scale.', 'Technical (specialised capital), purchasing (bulk-buy discounts), managerial (specialist managers), financial (cheaper borrowing), marketing, risk-bearing. They lower long-run AC as the firm grows.', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'What are diseconomies of scale?', 'The rise in long-run AC as a firm grows past its minimum efficient scale, due to coordination problems, communication breakdown, motivational issues and ''X-inefficiency'' from weak supervision.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Distinguish internal and external economies of scale.', 'Internal: arise within the firm as it grows. External: arise within the industry as a whole (skilled labour pool, specialist suppliers, infrastructure clustering — e.g. Silicon Valley).', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Define total, average and marginal revenue.', 'TR = P × Q. AR = TR/Q = price (same as the demand curve). MR = ΔTR/ΔQ. For a price taker AR = MR; for a price maker MR < AR and slopes more steeply.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'State the profit-maximisation rule.', 'Produce where MC = MR (and MC is rising). At this output, the gap between TR and TC is largest.', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Distinguish normal and supernormal (abnormal) profit.', 'Normal profit: minimum return needed to keep resources in their current use; counted as a cost in economics. Supernormal profit: any profit above normal — attracts new entrants in competitive markets.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'State the short-run shut-down rule.', 'A firm continues operating in the short run as long as price ≥ AVC, since it can still cover variable costs and contribute to fixed costs. If P < AVC, shut down to limit losses to fixed costs.', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Distinguish productive and allocative efficiency.', 'Productive efficiency: producing at minimum AC (no waste of resources). Allocative efficiency: producing the goods consumers value most, where P = MC, maximising society''s welfare.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'What is X-inefficiency?', 'A failure to minimise costs because firms lack competitive pressure — managerial slack, generous perks, bloated workforces. Common in monopolies and state monopolies.', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.4', 'Production, Costs and Revenue', 'Why might a firm have other objectives than profit-maximisation?', 'Imperfect information, principal-agent problems (managers maximise their own utility), satisficing (Simon), revenue or sales maximisation (Baumol), market-share targets, social/ethical aims.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'List the four assumptions of perfect competition.', 'Many small buyers and sellers (price takers); identical (homogeneous) products; perfect information; free entry and exit (no barriers).', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Why does a perfectly competitive firm face a horizontal demand curve?', 'Because it is a price taker — its output is too small to influence the market price. AR = MR = market price; any attempt to charge more loses all customers.', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'What happens to supernormal profits in perfect competition in the long run?', 'New firms are attracted by the profit, supply rises, market price falls until each remaining firm earns only normal profit. The long-run equilibrium has P = AC = MC = MR.', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Why is perfect competition both productively and allocatively efficient in the long run?', 'P = minimum AC (productive efficiency) and P = MC (allocative efficiency). Consumers get goods at the lowest possible cost equal to their valuation.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Define monopolistic competition and give an example.', 'Many firms selling slightly differentiated products with low entry barriers — e.g. hairdressers, restaurants. Each has a downward-sloping demand curve from product differentiation but earns only normal profit long run.', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'List four characteristics of an oligopoly.', 'Few large firms dominate, high concentration ratio, interdependent decisions, significant barriers to entry, products differentiated or homogeneous, non-price competition important.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'What is the n-firm concentration ratio?', 'The combined market share of the largest n firms. CR4 above ~50% suggests an oligopolistic structure. UK supermarkets have a high CR4.', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Explain the kinked demand curve.', 'In oligopoly, rivals match price cuts (so demand is inelastic below the kink) but ignore price rises (so demand is elastic above). MR has a vertical gap — explains observed price stability despite cost changes. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="35" x2="115" y2="75" stroke="#0B1E3F" stroke-width="1.5"/><line x1="115" y1="75" x2="195" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="55" x2="115" y2="95" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><line x1="115" y1="115" x2="170" y2="125" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><line x1="115" y1="95" x2="115" y2="115" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><circle cx="115" cy="75" r="2.5" fill="#0B1E3F"/><text x="115" y="68" font-size="8" fill="#0B1E3F" text-anchor="middle">kink</text><text x="198" y="125" font-size="9" fill="#0B1E3F">D</text><text x="170" y="135" font-size="9" fill="#0B1E3F">MR</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Distinguish collusive and non-collusive oligopoly.', 'Collusive: firms cooperate to fix prices/output (cartel) — illegal in UK/EU. Non-collusive: firms compete independently, often using price wars or non-price competition.', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'What does the prisoners'' dilemma reveal about cartels?', 'Each firm has an individual incentive to cheat by cutting price below the agreed level, even though all are worse off if they all cheat. Explains why cartels are unstable without strong enforcement.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'List three forms of non-price competition.', 'Advertising and branding, product differentiation/quality, after-sales service, loyalty schemes, packaging, location. Used to gain market share without triggering price wars.', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Define a pure monopoly and a working monopoly.', 'Pure: a single firm is the only seller. Working/legal: a firm with ≥ 25% market share — the share-of-supply threshold used in UK merger control (Enterprise Act 2002) — so it has significant market power. Abuse of dominance is policed under the Competition Act 1998.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'How does a profit-maximising monopolist set price and output?', 'Output where MC = MR; price read off the demand (AR) curve at that quantity. Result: higher P, lower Q than under perfect competition, with supernormal profit sustained by entry barriers. <svg viewBox="0 0 240 160" width="240" height="160" style="display:block;margin:6px auto"><line x1="30" y1="135" x2="225" y2="135" stroke="#0B1E3F"/><line x1="30" y1="135" x2="30" y2="20" stroke="#0B1E3F"/><line x1="40" y1="35" x2="195" y2="130" stroke="#0B1E3F" stroke-width="1.5"/><line x1="40" y1="35" x2="120" y2="130" stroke="#0B1E3F" stroke-width="1.5"/><path d="M40 90 Q90 130 130 95 T200 60" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><path d="M40 110 Q100 130 140 105 T210 75" stroke="#0B1E3F" stroke-width="1" fill="none" stroke-dasharray="3 2"/><line x1="30" y1="60" x2="100" y2="60" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="30" y1="92" x2="100" y2="92" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="100" y1="60" x2="100" y2="135" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><rect x="30" y="60" width="70" height="32" fill="#0B1E3F" fill-opacity="0.12"/><text x="198" y="130" font-size="9" fill="#0B1E3F">D=AR</text><text x="123" y="135" font-size="9" fill="#0B1E3F">MR</text><text x="200" y="62" font-size="9" fill="#0B1E3F">MC</text><text x="210" y="78" font-size="9" fill="#0B1E3F">AC</text><text x="28" y="63" font-size="9" fill="#0B1E3F" text-anchor="end">Pm</text><text x="100" y="148" font-size="9" fill="#0B1E3F" text-anchor="middle">Qm</text><text x="60" y="80" font-size="8" fill="#0B1E3F">profit</text></svg>', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Give two costs and two benefits of monopoly.', 'Costs: higher prices, lower output, allocative inefficiency, X-inefficiency. Benefits: economies of scale (lower AC), supernormal profits fund R&D and dynamic efficiency, may be a natural monopoly.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'Define a natural monopoly.', 'An industry where long-run AC keeps falling over the entire range of market demand — one firm can supply the market more cheaply than several. Examples: water, electricity grid, rail networks. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 35 C90 90 140 110 200 120" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="40" y1="40" x2="200" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><text x="200" y="35" font-size="9" fill="#0B1E3F" text-anchor="end">LRAC</text><text x="200" y="138" font-size="9" fill="#0B1E3F" text-anchor="end">D</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">£</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.5', 'Competitive and Concentrated Markets', 'What three conditions are needed for price discrimination?', 'Market power (firm is a price maker), ability to identify groups with different PEDs, and ability to prevent resale (no arbitrage). Examples: peak/off-peak rail fares, student/adult cinema tickets.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Why is the demand for labour called a derived demand?', 'Because firms do not want labour for its own sake — they want the output it produces. Demand for labour is derived from demand for the final good, so demand for bricklayers depends on demand for new housing.', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'State the formula for the marginal revenue product of labour.', 'MRP of labour = marginal physical product of labour (MPP) × marginal revenue (MR). In a perfectly competitive product market MR = price, so MRP = MPP × P.', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Why is the MRP curve the firm''s demand curve for labour, and why does it slope downwards?', 'A profit-maximising firm hires up to the point where MRP equals the marginal cost of labour, so at any wage it reads the quantity of labour it wants off MRP. It slopes down because diminishing marginal returns make MPP fall in the short run, and in an imperfectly competitive product market MR falls too.', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Give four influences that shift the demand for labour curve.', 'Demand for the final product (derived demand); labour productivity, which changes MPP and so MRP; the price of capital relative to labour, driving substitution towards machines; and non-wage employment costs such as employer National Insurance and pension contributions.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'What makes the demand for labour more wage elastic?', 'Labour is easily substituted by capital; labour costs are a high share of total costs; demand for the final product is price elastic, so the firm cannot pass on higher wages; and a longer time period, since in the long run production can be redesigned or relocated.', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Explain the income and substitution effects of a wage rise, and the shape they produce.', 'Substitution effect: a higher wage raises the opportunity cost of leisure, so the worker supplies more hours. Income effect: a higher wage lets the worker reach a target income with fewer hours, so if leisure is a normal good they supply fewer. At low wages substitution dominates; at high wages income dominates, giving a backward-bending individual supply curve. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="15" stroke="#0B1E3F"/><path d="M55 122 C 95 98 122 72 136 46 C 145 28 132 18 105 17" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Hours of labour</text><text x="28" y="13" font-size="9" fill="#0B1E3F" text-anchor="end">Wage</text><text x="148" y="52" font-size="8" fill="#0B1E3F">income effect</text><text x="60" y="100" font-size="8" fill="#0B1E3F">subs. effect</text></svg>', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'What are the net advantages of a job, and what is a compensating wage differential?', 'Net advantages are the whole package of monetary rewards (pay, bonus, pension, holiday) plus non-monetary ones (satisfaction, conditions, security, flexibility, status). A compensating differential is the extra pay needed to attract workers into jobs with poor non-monetary characteristics, such as offshore or night-shift work.', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'What determines the elasticity of supply of labour to an occupation?', 'The length and cost of the training required, how transferable the skills are, the time period (supply is far more elastic in the long run), the size and mobility of the pool of potential workers, and whether entry is restricted by licensing or registration.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'How are the wage and employment level set in a competitive labour market?', 'Where the market demand for labour (the sum of firms'' MRP curves) equals the market supply of labour. Each firm is a wage taker, so for the firm W = AC of labour = MC of labour. A rise in demand for labour raises both the wage and employment. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="15" stroke="#0B1E3F"/><line x1="45" y1="120" x2="190" y2="35" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="35" x2="190" y2="120" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="78" x2="117" y2="78" stroke="#0B1E3F" stroke-dasharray="3,2"/><line x1="117" y1="78" x2="117" y2="130" stroke="#0B1E3F" stroke-dasharray="3,2"/><text x="193" y="33" font-size="8" fill="#0B1E3F">S</text><text x="193" y="122" font-size="8" fill="#0B1E3F">D=MRP</text><text x="24" y="80" font-size="8" fill="#0B1E3F" text-anchor="end">We</text><text x="117" y="141" font-size="8" fill="#0B1E3F" text-anchor="middle">Le</text></svg>', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Define monopsony and state the two-step rule for reading the diagram.', 'A monopsony is a labour market with a single or dominant buyer of labour, which is therefore a wage maker. Step 1: employment is set where MC of labour = MRP. Step 2: the wage is read off the supply (AC of labour) curve at that employment level — never off MC or MRP. Both wage and employment are below the competitive outcome.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Why does the marginal cost of labour lie above the supply curve for a monopsonist?', 'Because the supply curve slopes up, hiring one more worker means offering a higher wage — and paying that higher wage to every worker already employed. The marginal cost is therefore the new worker''s wage plus the rise in the existing wage bill, so MC of labour is steeper than and above AC of labour, exactly as MR lies below AR for a monopoly seller.', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'What is the effect of a trade union in a competitive market compared with a monopsony?', 'In a competitive market a union wage above equilibrium raises pay but causes a contraction of labour demand, so employment falls and there is excess supply of labour. Facing a monopsonist it is a bilateral monopoly: the fixed wage makes the MC of labour constant, so the union can raise the wage AND employment towards the competitive level.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'What determines trade union bargaining power, and how unionised is the UK?', 'Union density, elasticity of demand for labour, employer profitability, the cost of disruption, legislation on ballots and secondary action, and the state of the economy. Department for Business and Trade figures for 2025 put UK density at 22.4% of employees — 48.5% in the public sector but only 12.1% in the private sector.', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'State the UK minimum wage rates that applied from April 2026.', 'National Living Wage £12.71 an hour for workers aged 21 and over, a 4.1% rise from £12.21. National Minimum Wage £10.85 for 18–20 year olds and £8.00 for 16–17 year olds and apprentices. Rates are recommended by the Low Pay Commission and were confirmed in the Autumn Budget of 26 November 2025.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'Compare the effect of a minimum wage in a competitive market and in a monopsony.', 'Competitive market: a floor above equilibrium creates excess supply of labour, so employment falls — by more the more elastic labour demand is. Monopsony: the effective MC of labour becomes horizontal at the legal wage, so the firm expands hiring and BOTH the wage and employment rise. UK rises since 1999 have caused smaller job losses than simple theory predicts, usually explained by monopsony power, moderate pre-announced increases, and firms absorbing costs through profits or productivity.', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.6', 'The Labour Market', 'What causes labour market failure, and what is the UK gender pay gap?', 'Causes: geographical and occupational immobility, skills shortages, imperfect information, monopsony power, discrimination, and the positive externalities of training that make it a merit good. Policies: education and training, housing and transport investment, better job matching, and anti-discrimination law. ONS ASHE for April 2025 put the median full-time gender pay gap at 6.9% (£20.27 for men against £18.87 for women), or 12.8% including part-timers — rising from 0.9% at ages 22–29 to 12.5% at 50–59.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Distinguish income from wealth.', 'Income is a FLOW of money received over a period of time (wages, rent, interest, dividends, profit, transfer payments). Wealth is a STOCK of assets owned at a single point in time, net of debt (property, private pensions, financial and physical assets).', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Explain the relationship between income and wealth.', 'Wealth generates income (rent, dividends, interest) without work; income not consumed is saved and accumulates into wealth, and higher earners save a larger share of each extra pound. Rising asset prices reward existing owners only, and inheritance passes the stock on intact — so the two reinforce each other across generations.', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'What does a Lorenz curve show?', 'The cumulative % of the population (poorest first) against the cumulative % of income they receive. The 45-degree line is perfect equality; the further the curve bows below it, the greater the inequality. It must run from (0,0) to (100,100). <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="30" y1="130" x2="150" y2="20" stroke="#0B1E3F" stroke-width="1.5"/><path d="M30 130 Q110 120 150 20" stroke="#0B1E3F" stroke-width="1.5" fill="none" stroke-dasharray="3 2"/><text x="103" y="84" font-size="9" fill="#0B1E3F">A</text><text x="100" y="118" font-size="9" fill="#0B1E3F">B</text><text x="153" y="18" font-size="8" fill="#0B1E3F">45 line</text><text x="152" y="62" font-size="8" fill="#0B1E3F">Lorenz</text><text x="32" y="16" font-size="9" fill="#0B1E3F">% income</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">% population</text></svg>', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'How is the Gini coefficient calculated and interpreted?', 'Gini = A / (A + B), where A is the area between the 45-degree line and the Lorenz curve and B is the area beneath the Lorenz curve. 0 = perfect equality (A = 0); 1 = perfect inequality (B = 0). A rising Gini means inequality is increasing. Often quoted as a percentage from 0 to 100.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Give the UK Gini coefficients for income and for wealth.', 'Income (DWP Households Below Average Income, 2024/25): 33% before housing costs and 37% after housing costs. Wealth (ONS Wealth and Assets Survey, April 2020 to March 2022, Great Britain): 0.59. Wealth is therefore far more unequally distributed than income. OECD comparisons put UK income inequality among the highest in Europe, below the United States.', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'List the AQA causes of inequality in the distribution of income and wealth.', 'Wage differentials; unemployment; age and the life cycle; inheritance; ownership of assets; differences in human capital; discrimination; household composition.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'State the strengths and limitations of the Gini coefficient.', 'Strengths: one number, easy to compare across countries and over time; sensitive to the whole distribution; widely published. Limitations: two very different distributions can share a Gini; it does not say whether inequality arises at the top or the bottom; it ignores absolute living standards; surveys under-record top incomes.', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Give the UK quintile and decile income shares.', 'In 2023/24 the top fifth of individuals received 35% of total disposable household income and the bottom fifth received 8% (a quintile ratio of about 4.4). In 2024/25 a couple with no children needed under £366 a week before housing costs for the lowest tenth, and at least £1,358 a week for the highest tenth — 3.7 times as much.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'What is the difference between income measured before and after housing costs?', 'BHC includes the money later spent on rent or mortgage interest; AHC deducts rent, mortgage interest, water charges and buildings insurance first. Housing takes a larger share of low incomes, so AHC is always more unequal — 33% BHC against 37% AHC in 2024/25 — and is the better guide to living standards for renters.', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Distinguish absolute poverty from relative poverty.', 'Absolute poverty: income too low to afford basic necessities, measured against a fixed real threshold. Relative poverty: income below the UK official line of 60% of contemporary median household income, equivalised for household size. Growth that lifts all incomes proportionately cuts absolute poverty but leaves relative poverty unchanged; a recession that cuts the median can lower measured relative poverty.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Give the UK relative poverty figures for 2024/25.', '20% of individuals were in relative low income after housing costs, unchanged on 2023/24. Relative child poverty AHC was 31%, and has been between 27% and 31% every year since 2001/02. The rate was 45% for children in families with three or more children and 58% for children in workless families. In July 2026 the government projected relative child poverty AHC would fall by 400,000 by 2029/30.', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Summarise the Joseph Rowntree Foundation UK Poverty 2026 findings.', 'Using 2023/24 data: 14.2 million people, 21% of the population, were in poverty, including 4.5 million children (about 3 in 10) and 7.9 million working-age adults; around 3 in 20 pensioners. 6.8 million people were in very deep poverty (income at most two-thirds of the poverty line) — the highest number and share on record since 1994/95. About 3.8 million people, including around 1 million children, experienced destitution in 2022.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'What is the composition of UK household wealth?', 'ONS Wealth and Assets Survey, April 2020 to March 2022: net property 40%, private pension 35%, net financial 14%, physical 10%. The wealthiest tenth of households held around 43% of all wealth and needed £1,200,500 or more; the least wealthy half held about 9%. Most UK wealth is therefore illiquid, tied up in housing and pensions.', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Explain the poverty trap and the unemployment trap.', 'Poverty trap: a low-income household raising its earnings pays income tax and NICs while losing means-tested benefits, so its effective marginal tax rate is very high and the net gain is small. The Universal Credit taper has been 55% since November 2021. Unemployment trap: out-of-work income is close to net income in work, so the replacement ratio (out-of-work income / in-work income) is high and there is little incentive to take a job. Both are examples of government failure.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Compare means-tested and universal benefits.', 'Means-tested (Universal Credit, Pension Credit): better targeted, lower payment cost, but incomplete take-up through stigma and complexity, high administration cost, and a withdrawal taper that creates the poverty trap. Universal (state pension, free schooling, NHS treatment): full take-up, no stigma, no taper and broad political support, but very expensive and much of the money goes to households that do not need it.', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.7', 'The Distribution of Income and Wealth', 'Explain the equity-efficiency trade-off and the Laffer curve argument.', 'Equity is fairness (normative); equality is a factual description of the distribution. Redistribution may improve equity at the cost of efficiency — Okun called it carrying money in a leaky bucket. High marginal rates may weaken incentives to work, train, take risk or stay in the country. The Laffer curve shows revenue rising with the tax rate up to t*, then falling as disincentives, avoidance and evasion dominate; it shows that some rate maximises revenue, not where that rate lies. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 130 Q110 -50 180 130" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="110" y1="40" x2="110" y2="130" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><line x1="30" y1="40" x2="110" y2="40" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><text x="110" y="142" font-size="9" fill="#0B1E3F" text-anchor="middle">t*</text><text x="28" y="43" font-size="8" fill="#0B1E3F" text-anchor="end">Rmax</text><text x="32" y="16" font-size="9" fill="#0B1E3F">Revenue</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Tax rate</text></svg>', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Define market failure.', 'When the free market fails to allocate resources efficiently, leading to a loss of social welfare. Includes externalities, public goods, information failure, monopoly power and inequality.', 1, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Distinguish private, external and social cost.', 'Private cost: borne by the producer/consumer. External cost: spillover onto third parties (pollution). Social cost = private + external. The free market ignores external costs, leading to overproduction.', 2, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'How do you identify a negative production externality on a diagram?', 'MSC lies above MPC. The free-market output (where MPB = MPC) exceeds the socially optimum output (where MSB = MSC), creating a deadweight welfare loss triangle. <svg viewBox="0 0 240 150" width="240" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="225" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="30" x2="200" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="125" x2="200" y2="30" stroke="#0B1E3F" stroke-width="1.5"/><line x1="65" y1="125" x2="220" y2="22" stroke="#0B1E3F" stroke-width="1.5" stroke-dasharray="3 2"/><polygon points="115,75 145,55 145,90" fill="#B00020" fill-opacity="0.3"/><text x="203" y="125" font-size="9" fill="#0B1E3F">D=MPB</text><text x="203" y="30" font-size="9" fill="#0B1E3F">MPC</text><text x="223" y="20" font-size="9" fill="#0B1E3F" text-anchor="end">MSC</text><text x="118" y="80" font-size="8" fill="#B00020">DWL</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="225" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 3, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'What are merit and demerit goods?', 'Merit goods: undervalued by consumers, underconsumed (education, healthcare). Demerit goods: overvalued, overconsumed (cigarettes, alcohol). Reflect information failure and positive/negative externalities.', 4, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'State the two characteristics of a public good.', 'Non-rival (one person''s use does not reduce another''s) and non-excludable (no one can be prevented from using it). Examples: street lighting, national defence. Free-rider problem leads to under-provision.', 5, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'What is the free-rider problem?', 'Because public goods are non-excludable, individuals can benefit without paying. Profit-maximising firms cannot recoup costs, so the good is under-provided by the market — justifying state provision.', 6, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'How does asymmetric information cause market failure?', 'When one party in a transaction has more information than the other, leading to adverse selection (used-car market — Akerlof''s lemons) and moral hazard (insured drivers take more risks).', 7, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Evaluate an indirect tax to correct a negative externality.', 'Strengths: internalises external cost (Pigouvian), generates revenue to compensate victims, signals harm. Weaknesses: hard to set at exactly MEC, regressive, may push activity into black markets, inelastic demand limits effect on quantity.', 8, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'How does a tradeable pollution permit (cap-and-trade) work?', 'Government caps total emissions and issues permits. Firms that pollute below their allowance sell surplus permits; heavy polluters must buy. Market price of permits reflects MEC; cap can be tightened over time. Used by the EU ETS and, since 2021, the separate UK ETS.', 9, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'What is a subsidy and a likely diagrammatic effect?', 'A government grant that reduces production cost or consumption price. It shifts supply rightward (or demand rightward if to consumers), raising output to the socially optimum level for goods with positive externalities.', 10, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Compare maximum and minimum prices.', 'Maximum (price ceiling) below equilibrium creates a shortage and possible black market (e.g. rent controls). Minimum (price floor) above equilibrium creates a surplus and may need government to buy the excess (the EU CAP''s intervention buying, historically; the UK National Living Wage is a wage floor). <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="45" y1="30" x2="195" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="125" x2="195" y2="30" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="50" x2="205" y2="50" stroke="#B00020" stroke-width="1.2"/><line x1="30" y1="105" x2="205" y2="105" stroke="#B00020" stroke-width="1.2" stroke-dasharray="4 2"/><text x="208" y="52" font-size="9" fill="#B00020">P min (floor)</text><text x="208" y="107" font-size="9" fill="#B00020">P max (ceiling)</text><text x="198" y="125" font-size="9" fill="#0B1E3F">D</text><text x="198" y="30" font-size="9" fill="#0B1E3F">S</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 11, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Why might competition policy be needed?', 'To prevent abuse of monopoly power — anti-competitive mergers, predatory pricing, price-fixing cartels — and protect consumers from high prices and low choice. Enforced by the CMA in the UK.', 12, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Distinguish privatisation, deregulation and nationalisation.', 'Privatisation: transfer of state assets to private sector. Deregulation: removal of restrictive rules to allow competition. Nationalisation: transfer of private firms into state ownership.', 13, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'What is regulatory capture?', 'When the regulator comes to act in the interests of the industry it regulates rather than consumers, due to lobbying, revolving doors of personnel, or asymmetric information.', 14, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Define government failure.', 'When intervention to correct market failure produces a worse allocation of resources — caused by information gaps, unintended consequences, administrative costs, lobbying and short-termism.', 15, 'alevel'),
  ('Economics', 'AQA', '3.1.8', 'Market Failure and Government Intervention', 'Give an example of unintended consequences of government intervention.', 'Rent controls reducing housing supply and quality; cigarette taxes funding smuggling; subsidies for biofuels raising food prices; minimum alcohol pricing reducing problem drinking but hitting low-income moderate drinkers.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'List the four main macroeconomic objectives.', 'Sustainable economic growth, low and stable inflation (~2% CPI), low unemployment (full employment), satisfactory balance of payments on current account. Often add: budget balance, fairer income distribution, environmental sustainability.', 1, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Distinguish nominal and real GDP.', 'Nominal GDP = output valued at current prices. Real GDP = output valued at constant (base-year) prices. Real GDP strips out inflation, so changes in real GDP reflect actual changes in output.', 2, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Why use GDP per capita instead of total GDP?', 'Total GDP rises with population. Dividing by population reflects average income/output per person — a better proxy for living standards across countries of different size.', 3, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Give three limitations of GDP as a measure of welfare.', 'Ignores income distribution; excludes the informal/black economy and household production; ignores environmental damage; says nothing about leisure, health or political freedom.', 4, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the Human Development Index?', 'A UN composite index combining life expectancy, mean/expected years of schooling and GNI per capita (PPP) into a 0-1 score. Captures more dimensions of welfare than GDP alone.', 5, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'How is CPI calculated?', 'A weighted average of the prices of a representative basket of goods and services consumed by a typical household, weights based on Living Costs and Food Survey. Updated annually.', 6, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Distinguish CPI from RPI.', 'CPI excludes most housing costs and uses a geometric mean (substitution effect) — generally lower. RPI includes mortgage interest and council tax and uses arithmetic mean. Bank of England targets CPI.', 7, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'List three limitations of CPI.', 'Slow to capture quality changes; excludes owner-occupiers'' housing costs (CPIH includes them); basket is updated annually but tastes can change quickly; it is an average household''s basket, so it does not reflect any particular household''s spending pattern.', 8, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'How is unemployment measured (UK)?', 'Two main methods: claimant count (those receiving JSA/Universal Credit) — narrow and quick; ILO/Labour Force Survey (out of work, actively sought work in the last four weeks and available to start within two weeks) — internationally comparable, broader.', 9, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Define the activity (participation) rate.', 'The economically active population (employed + unemployed) as a percentage of the working-age population. Rises if more women, students or older people enter the labour force.', 10, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'What does the balance of payments record?', 'All economic transactions between residents of the UK and the rest of the world over a period. Made up of the current account, capital account and financial account; sum should equal zero (with errors and omissions).', 11, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'List the four parts of the current account.', 'Trade in goods, trade in services, primary income (wages/investment income from abroad), secondary income (transfers — remittances, EU/UN payments, foreign aid).', 12, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'What does an index number tell you?', 'It re-bases a series so that the value in a chosen base year equals 100. Other values express the percentage change relative to that base, simplifying comparison over time.', 13, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'What is the difference between GDP and GNI?', 'GDP measures output produced within a country''s borders. GNI measures income earned by that country''s residents wherever produced. GNI = GDP + net primary income from abroad.', 14, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Define purchasing power parity (PPP).', 'An exchange rate that equalises the cost of a basket of goods in two countries. Using PPP rather than market rates makes cross-country GDP comparisons more meaningful — The Economist''s Big Mac Index is a popular illustration.', 15, 'alevel'),
  ('Economics', 'AQA', '3.2.1', 'Measurement of Macroeconomic Performance', 'Distinguish absolute from relative poverty.', 'Absolute: income too low to afford basic essentials (World Bank: $3.00 a day at 2021 PPP since June 2025; previously $2.15 at 2017 PPP). Relative: income below a threshold (commonly 60% of median income in the UK) — measures inequality more than survival.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Write the AD equation.', 'AD = C + I + G + (X − M). Consumption + investment + government spending + net exports.', 1, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Why does AD slope downwards?', 'Real-balance effect (lower price level raises real wealth and consumption); interest-rate effect (lower P -> lower money demand -> lower r -> more I); international trade effect (lower P makes exports more competitive).', 2, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Name three determinants of consumption.', 'Disposable income, interest rates, wealth (housing/financial), consumer confidence, expectations, availability of credit, taxation. The marginal propensity to consume falls as income rises.', 3, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Distinguish gross and net investment.', 'Gross investment = total spending on new capital goods. Net investment = gross investment minus capital depreciation (replacement). Net investment expands the capital stock and productive capacity.', 4, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Give three determinants of investment.', 'Expected returns/animal spirits, interest rates, business confidence, taxation/allowances, technology, retained profits, the accelerator effect (changes in demand drive investment).', 5, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'List four causes of an increase in AD.', 'Cuts in income tax, lower interest rates, weaker pound (boosts X, raises M cost), rising house prices, rising consumer/business confidence, higher government spending, faster world growth.', 6, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Distinguish SRAS and LRAS.', 'SRAS: upward-sloping; in the short run, higher P with sticky wages raises profit and output. LRAS: vertical at full-employment output (Yfe) on the classical view, or upward-sloping/curved on the Keynesian view (spare capacity).', 7, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'List three factors that shift LRAS.', 'Quantity/quality of labour (immigration, education), capital stock and investment, technology and productivity, enterprise/incentives, government supply-side policy (deregulation, infrastructure).', 8, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Compare classical and Keynesian LRAS curves.', 'Classical: vertical at Yfe — output cannot exceed potential, so AD changes only affect P. Keynesian: horizontal at low output, upward-sloping with spare capacity, vertical near Yfe — AD matters at low output. <svg viewBox="0 0 460 160" width="460" height="160" style="display:block;margin:6px auto"><g><line x1="30" y1="135" x2="200" y2="135" stroke="#0B1E3F"/><line x1="30" y1="135" x2="30" y2="20" stroke="#0B1E3F"/><line x1="140" y1="135" x2="140" y2="25" stroke="#0B1E3F" stroke-width="1.5"/><line x1="40" y1="30" x2="180" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><text x="200" y="148" font-size="9" fill="#0B1E3F" text-anchor="end">Y</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="143" y="20" font-size="9" fill="#0B1E3F">LRAS</text><text x="183" y="125" font-size="9" fill="#0B1E3F">AD</text><text x="115" y="155" font-size="9" fill="#0B1E3F" text-anchor="middle">Classical</text></g><g><line x1="260" y1="135" x2="440" y2="135" stroke="#0B1E3F"/><line x1="260" y1="135" x2="260" y2="20" stroke="#0B1E3F"/><path d="M260 110 L320 110 Q360 100 380 60 L380 25" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="270" y1="35" x2="420" y2="125" stroke="#0B1E3F" stroke-width="1.5"/><text x="440" y="148" font-size="9" fill="#0B1E3F" text-anchor="end">Y</text><text x="258" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">P</text><text x="383" y="22" font-size="9" fill="#0B1E3F">LRAS</text><text x="423" y="125" font-size="9" fill="#0B1E3F">AD</text><text x="350" y="155" font-size="9" fill="#0B1E3F" text-anchor="middle">Keynesian</text></g></svg>', 9, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Define the multiplier and give the formula.', 'The ratio of final change in real GDP to the initial change in injections. k = 1/(1 − MPC) = 1/MPS in a closed economy with no government; in an open economy k = 1/(MPS + MPT + MPM).', 10, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'What determines the size of the multiplier?', 'The marginal propensities to consume (raises k) and to withdraw — save, tax, import (lowers k). Also depends on spare capacity: with little spare capacity, extra spending mostly raises prices.', 11, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'List the injections and withdrawals in the circular flow.', 'Injections: investment (I), government spending (G), exports (X). Withdrawals: saving (S), taxation (T), imports (M). Equilibrium: I + G + X = S + T + M.', 12, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'What is the accelerator effect?', 'The relationship by which a change in the rate of growth of output causes a much larger proportional change in investment, since firms only invest when expected demand growth justifies new capacity.', 13, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'How does an outward shift of AD affect P and Y on a Keynesian AS curve?', 'On the horizontal section: Y rises with P unchanged. On the upward-sloping section: P and Y both rise. On the vertical section: P rises with Y unchanged (pure inflation).', 14, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'Why is consumer confidence important to AD?', 'Confidence shapes household saving and borrowing decisions, especially for big-ticket items. Falling confidence raises saving (precautionary motive) and lowers C, contracting AD.', 15, 'alevel'),
  ('Economics', 'AQA', '3.2.2', 'How the Macroeconomy Works', 'What is Say''s Law and which school accepts it?', 'Say''s Law: ''supply creates its own demand'' — production generates incomes that are spent on output. Accepted by classical economists, rejected by Keynes who argued saving may exceed investment.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Distinguish actual and trend (potential) growth.', 'Actual growth = change in real GDP year on year. Trend growth = the long-run sustainable rate at which the economy can grow without rising inflation, set by the supply-side fundamentals.', 1, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'List the four phases of the business cycle.', 'Recovery, boom (peak), slowdown, recession (trough). A recession is technically two consecutive quarters of negative real GDP growth.', 2, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'List four potential benefits of economic growth.', 'Higher living standards, higher tax revenue, lower unemployment, easier to redistribute, more government spending on public services, fiscal dividend, business confidence.', 3, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Give three costs of rapid economic growth.', 'Demand-pull inflation, current-account deficit (rising imports), environmental damage, widening inequality, resource depletion, working-time pressure on welfare.', 4, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Distinguish demand-pull and cost-push inflation.', 'Demand-pull: AD rises faster than AS — ''too much money chasing too few goods''. Cost-push: rising costs (wages, oil, taxes, weaker pound) shift SRAS leftward, raising P and lowering Y (stagflation possible).', 5, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Give the Fisher equation of exchange.', 'MV = PT. Money supply × velocity of circulation = price level × volume of transactions. Monetarists assume V and T are stable, so changes in M cause proportional changes in P.', 6, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'List four costs of high inflation.', 'Erodes purchasing power; menu costs; shoe-leather costs; uncertainty deters investment; loss of international competitiveness; income redistribution from creditors to debtors; ''fiscal drag''.', 7, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Why is deflation a problem?', 'Consumers delay purchases waiting for lower prices, depressing AD. Real value of debt rises, increasing default risk and bank stress (debt-deflation, Fisher 1933). Hard for central banks to escape with rates at zero.', 8, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'List four causes of unemployment.', 'Cyclical (demand-deficient), structural (mismatched skills/regions), frictional (between jobs), seasonal, real-wage (wages above clearing), classical/voluntary.', 9, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Give four costs of unemployment.', 'Lost output (operating inside PPF), lower tax revenue, higher benefits, hysteresis (long-term unemployed lose skills), social problems (mental health, crime), inequality.', 10, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'What does the short-run Phillips curve show?', 'A short-run inverse relationship between inflation and unemployment — lower unemployment requires higher inflation. Fitted by Phillips (1958) to UK data from 1861-1957 and relied on through the 1960s; it broke down in the 1970s under stagflation. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M40 35 Q90 60 130 95 T200 125" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><text x="200" y="35" font-size="9" fill="#0B1E3F" text-anchor="end">SRPC</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">π</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">U</text></svg>', 11, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'What does the long-run Phillips curve look like and why?', 'Vertical at the Natural Rate of Unemployment (NAIRU). Friedman: any attempt to push unemployment below NAIRU only raises inflation as workers update expectations. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="120" y1="130" x2="120" y2="25" stroke="#0B1E3F" stroke-width="1.5"/><path d="M40 50 Q70 65 100 90 T160 130" stroke="#0B1E3F" stroke-width="1" fill="none" stroke-dasharray="3 2"/><path d="M70 35 Q100 50 130 75 T190 125" stroke="#0B1E3F" stroke-width="1" fill="none" stroke-dasharray="3 2"/><text x="123" y="22" font-size="9" fill="#0B1E3F">LRPC</text><text x="170" y="125" font-size="8" fill="#0B1E3F">SRPC</text><text x="120" y="145" font-size="9" fill="#0B1E3F" text-anchor="middle">NAIRU</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">π</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">U</text></svg>', 12, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'List two causes of a current-account deficit.', 'Strong domestic demand (sucking in imports), overvalued exchange rate, low productivity/competitiveness, deindustrialisation, slow growth in trading partners, high domestic inflation.', 13, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'Why might a current-account deficit not be a problem?', 'It can reflect productive investment financed by capital inflows; reserve-currency status (US dollar) means the deficit can be funded easily; consumers benefit from cheap imports.', 14, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'How does the Marshall-Lerner condition relate to a depreciation?', 'A depreciation improves the current-account balance only if |PEDx| + |PEDm| > 1. Short-run elasticities are low (J-curve), so the deficit may worsen before improving. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="80" x2="205" y2="80" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 80 Q70 130 110 95 T200 25" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="50" y1="78" x2="50" y2="82" stroke="#0B1E3F"/><text x="50" y="95" font-size="8" fill="#0B1E3F" text-anchor="middle">depreciation</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">CA balance</text><text x="205" y="78" font-size="9" fill="#0B1E3F" text-anchor="end">time</text></svg>', 15, 'alevel'),
  ('Economics', 'AQA', '3.2.3', 'Economic Performance', 'What is hysteresis in the labour market?', 'The persistence of unemployment after the original shock has passed, because the long-term unemployed lose skills, motivation and employability — raising the natural rate.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'List three roles of financial markets.', 'Channel funds from savers to borrowers, allocate capital efficiently, provide liquidity, price assets and risk, allow firms and governments to raise capital.', 1, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Distinguish the money market from the capital market.', 'Money market: short-term debt instruments (under one year — Treasury bills, certificates of deposit, commercial paper). Capital market: long-term funds (shares and bonds with maturities of >1 year).', 2, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'What is the inverse relationship between bond prices and yields?', 'A bond pays a fixed coupon. If its market price falls, the coupon represents a higher % of the price — yield rises. Conversely, when bond demand rises, prices rise and yields fall.', 3, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'List three functions of commercial banks.', 'Accept deposits, make loans, provide payment services. Also offer foreign exchange, financial advice and credit/debit cards. Profit comes from the spread between deposit and loan interest rates.', 4, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'How do banks create credit?', 'When a bank makes a loan, it credits the borrower''s deposit account, expanding the money supply. Constrained by required reserves, capital ratios and demand for loans.', 5, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'List the four functions of a central bank.', 'Sole issuer of banknotes in England and Wales, banker to government, banker to commercial banks, lender of last resort. Conducts monetary policy and oversees financial stability (Prudential Regulation Authority in UK).', 6, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Define moral hazard in banking.', 'When the protection offered by deposit insurance, bailouts or ''too big to fail'' status encourages banks to take excessive risk because they bear less of the downside.', 7, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Outline the 2007-09 financial crisis in three sentences.', 'US sub-prime mortgages were bundled into mortgage-backed securities and sold globally. Defaults rose, exposing leveraged banks to huge losses; interbank lending froze. Major banks failed (Lehman) or were bailed out, triggering a global recession.', 8, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'What is monetary policy?', 'The use of interest rates and the money supply to influence AD and meet the inflation target. In the UK, set by the Bank of England''s nine-member Monetary Policy Committee, targeting 2% CPI.', 9, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Through what four channels does Bank Rate transmit to inflation?', 'Market interest rates (mortgages, savings), asset prices (housing, shares), confidence/expectations, exchange rate. Each affects C, I, X-M and ultimately AD and inflation, with lags of 12-24 months.', 10, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'What is quantitative easing (QE)?', 'A central bank creates new money electronically to buy government bonds (and other assets), pushing up bond prices, lowering long-term yields, raising asset prices and bank reserves to stimulate AD when Bank Rate is near zero.', 11, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Give two limitations of monetary policy.', 'Liquidity trap (rates near zero cannot fall further); time lags; uncertain transmission via banks; if banks won''t lend or households deleverage, low rates have little effect; widens inequality (asset-price boom).', 12, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Distinguish micro- and macro-prudential regulation.', 'Microprudential focuses on stability of individual banks (capital, liquidity ratios). Macroprudential targets the financial system as a whole, e.g. counter-cyclical capital buffers, loan-to-income limits — overseen by the FPC in the UK.', 13, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'What is the difference between liquidity and solvency?', 'Liquidity: ability to meet short-run cash demands without distressed sale. Solvency: assets exceed liabilities. A bank can be solvent but illiquid (Northern Rock 2007).', 14, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'What are the Basel III capital requirements aimed at?', 'Strengthening bank resilience by raising minimum core capital ratios, introducing leverage and liquidity coverage ratios, and adding counter-cyclical buffers.', 15, 'alevel'),
  ('Economics', 'AQA', '3.2.4', 'Financial Markets and Monetary Policy', 'Define the term structure (yield curve) of interest rates.', 'The relationship between yields on bonds of equal credit quality but different maturities. Normally upward-sloping; an inverted curve (long < short) often precedes a recession.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Define fiscal policy.', 'The use of government spending (G) and taxation (T) to influence AD, redistribute income and provide public goods. Set by the Treasury in the annual Budget.', 1, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Distinguish direct and indirect taxes.', 'Direct: levied on income/wealth (income tax, NI, corporation tax) — paid by the person on whom it''s charged. Indirect: levied on spending (VAT, excise duties, fuel duty) — incidence can shift between buyer and seller.', 2, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Define progressive, proportional and regressive taxes.', 'Progressive: average tax rate rises with income (UK income tax). Proportional: flat % of income. Regressive: average rate falls as income rises (VAT, council tax).', 3, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'List the four canons of taxation (Adam Smith).', 'Equity (ability to pay), certainty (clear amount/timing), convenience (easy to pay), economy (low collection cost). Modern additions: efficiency, flexibility, transparency.', 4, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'What is the difference between a budget deficit and the national debt?', 'A budget deficit is the gap between G and T in a single year (a flow). The national debt is the cumulative total of past borrowing (a stock). The deficit adds to the debt.', 5, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Distinguish cyclical and structural budget deficits.', 'Cyclical: arises automatically when output is below trend (lower tax, higher benefits). Structural: persists at full employment, signalling that fiscal policy is fundamentally unsustainable.', 6, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Define automatic stabilisers.', 'Features of the tax/benefits system that dampen the cycle without explicit policy change: tax revenues fall and benefits rise in a recession; both reverse in a boom.', 7, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Describe expansionary fiscal policy and a likely effect on AD.', 'Cuts in taxes or rises in G shift AD right via the multiplier, raising output and employment in the short run, especially in a recession with spare capacity.', 8, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'What is crowding out?', 'When higher government borrowing pushes up interest rates and absorbs available savings, reducing private investment and consumption. Most relevant near full employment.', 9, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'List four UK fiscal rules used in recent years.', 'Current (2026) rules: the stability rule (current budget in balance or surplus by a set forecast year) and the investment rule (public sector net financial liabilities falling as a share of GDP by year five). Earlier rules used cyclically-adjusted balances, a debt/GDP target and a welfare cap. Specific rules change with government.', 10, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Define supply-side policies.', 'Policies designed to raise the productive capacity (LRAS) and improve the long-run growth rate by improving the quantity or quality of factors of production and the efficiency of markets.', 11, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Distinguish market-based and interventionist supply-side policies.', 'Market-based: free up markets — cut income/corporation tax, deregulation, privatisation, lower trade-union power. Interventionist: government action — infrastructure, education, R&D subsidies, training schemes.', 12, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Give three benefits and two costs of supply-side policies.', 'Benefits: higher non-inflationary growth, lower structural unemployment, better trade balance. Costs: long time lags, regressive income effects of tax cuts, potential to worsen inequality, fiscal cost.', 13, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'What is the Laffer curve?', 'A graph showing tax revenue against tax rate. Revenue rises then falls as the rate rises beyond an optimum, because high rates discourage work, encourage avoidance and shrink the tax base. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><path d="M30 130 Q115 0 200 130" stroke="#0B1E3F" stroke-width="1.5" fill="none"/><line x1="115" y1="130" x2="115" y2="60" stroke="#0B1E3F" stroke-width="0.5" stroke-dasharray="2 2"/><circle cx="115" cy="60" r="2.5" fill="#0B1E3F"/><text x="115" y="55" font-size="8" fill="#0B1E3F" text-anchor="middle">t*</text><text x="28" y="18" font-size="9" fill="#0B1E3F" text-anchor="end">Revenue</text><text x="205" y="145" font-size="9" fill="#0B1E3F" text-anchor="end">Tax rate</text></svg>', 14, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Why might monetary and fiscal policy need to be coordinated?', 'They influence AD jointly. A loose fiscal stance combined with tight monetary policy creates conflicting signals, raising long-term rates and worsening the policy mix; coordination improves outcomes.', 15, 'alevel'),
  ('Economics', 'AQA', '3.2.5', 'Fiscal and Supply-Side Policies', 'Explain the Office for Budget Responsibility (OBR).', 'An independent UK body created in 2010 that produces official forecasts of growth, inflation and the public finances, and judges whether the government is meeting its fiscal rules.', 16, 'alevel');
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level) VALUES
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Define globalisation and give four of its characteristics.', 'The increasing integration and interdependence of national economies. Characteristics: rising trade as a share of world GDP; fragmented global supply chains; growing flows of foreign direct investment; increased migration of labour; integrated financial markets; convergence of consumer tastes; growing influence of MNCs and bodies such as the WTO.', 1, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'List the main causes of globalisation.', 'Falling transport costs (containerisation, cheap air freight); falling communication and IT costs (internet, cloud); trade liberalisation through GATT/WTO and regional agreements; deregulation of financial markets and removal of capital controls (UK 1979); the opening of China (reforms from 1978, WTO accession 2001) and the collapse of the Soviet bloc; the growth of MNCs building global supply chains.', 2, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Why do firms become multinational, and what are the costs to a host country?', 'Motives: lower labour, land or raw material costs; market access and tariff jumping; economies of scale; access to raw materials; lighter regulation and tax. Costs to the host: profits repatriated (a debit on primary income); local firms driven out by monopoly/monopsony power; environmental damage and poor conditions where regulation is weak; transfer pricing means little tax is paid; footloose capital can relocate at short notice.', 3, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Distinguish absolute advantage from comparative advantage.', 'Absolute advantage: a country can produce more of a good than another using the same resources. Comparative advantage: a country can produce a good at a lower opportunity cost than another. Ricardo (1817) showed that trade is mutually beneficial whenever opportunity costs differ, even if one country has an absolute advantage in everything. If the opportunity cost ratios are identical, there is no comparative advantage and no gain from trade.', 4, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Country A can make 200 machines or 400 textiles; Country B can make 100 machines or 300 textiles. Who has the comparative advantage in each good, and what are the acceptable terms of trade?', 'A: 1 machine costs 2 textiles; B: 1 machine costs 3 textiles, so A has the comparative advantage in machines. B: 1 textile costs 0.33 machines; A: 1 textile costs 0.5 machines, so B has the comparative advantage in textiles (even though A has an absolute advantage in both). Mutually beneficial terms of trade lie between 1 machine = 2 textiles and 1 machine = 3 textiles.', 5, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Give five limiting assumptions of the theory of comparative advantage.', 'Constant opportunity costs and constant returns to scale (straight-line PPFs); zero transport costs; no trade barriers; perfect factor mobility within countries, so adjustment costs and structural unemployment are ignored; factors assumed immobile between countries, yet capital and labour are now highly mobile; only two countries and two homogeneous goods, so intra-industry trade is unexplained. Also note the risk of over-specialisation and, for primary exporters, the Prebisch-Singer hypothesis of a long-run deterioration in the terms of trade.', 6, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Name the instruments of protection and say how the terms of trade are calculated.', 'Tariff (a tax on imports, specific or ad valorem); quota (a physical limit on import volume); subsidy to domestic producers (shifts domestic supply right without raising the consumer price); non-tariff barriers (standards, rules of origin, SPS checks, customs paperwork); embargo (a complete ban); and exchange rate manipulation. Terms of trade = (index of export prices / index of import prices) x 100.', 7, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'On a tariff diagram, what are the four welfare areas?', 'Price rises from Pw to Pw+T. Consumers lose surplus equal to a+b+c+d. Area a is the gain in producer surplus; area c is government tariff revenue (tariff x imports after the tariff); both are transfers, not net gains. Areas b and d are the production and consumption deadweight losses, so the net welfare effect is -(b+d). <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><rect x="103" y="85" width="24" height="15" fill="#0B1E3F" fill-opacity="0.18"/><line x1="45" y1="120" x2="185" y2="35" stroke="#0B1E3F" stroke-width="1.5"/><line x1="45" y1="35" x2="185" y2="120" stroke="#0B1E3F" stroke-width="1.5"/><line x1="30" y1="100" x2="198" y2="100" stroke="#0B1E3F" stroke-width="1"/><line x1="30" y1="85" x2="198" y2="85" stroke="#0B1E3F" stroke-width="1" stroke-dasharray="3 2"/><text x="188" y="33" font-size="8" fill="#0B1E3F">S</text><text x="188" y="122" font-size="8" fill="#0B1E3F">D</text><text x="28" y="103" font-size="8" fill="#0B1E3F" text-anchor="end">Pw</text><text x="28" y="88" font-size="8" fill="#0B1E3F" text-anchor="end">Pw+T</text><text x="113" y="96" font-size="8" fill="#0B1E3F" text-anchor="middle">c</text><text x="205" y="145" font-size="8" fill="#0B1E3F" text-anchor="end">Q</text></svg>', 8, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Give the main arguments for and against protectionism.', 'For: the infant industry argument; protecting employment and preventing structural unemployment; preventing dumping (anti-dumping duties are permitted by WTO rules); correcting a current account deficit; strategic, food and national security; raising government revenue; preventing a race to the bottom on environmental and labour standards. Against: higher prices and a regressive hit to consumers; misallocation of resources (deadweight loss); X-inefficiency from reduced competition; higher input costs for downstream firms; retaliation and trade wars; damage to developing-country exporters.', 9, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Set out the structure of the balance of payments and the recent UK position.', 'Current account: trade in goods, trade in services, primary income (cross-border wages and investment income), secondary income (transfers such as aid and remittances). Capital account: capital transfers and non-produced, non-financial assets. Financial account: FDI, portfolio investment, other investment, reserve assets. The accounts sum to zero. UK: the underlying current account deficit excluding precious metals was £15.1bn, or 1.9% of GDP, in Q2 2026, down from £18.2bn (2.4% of GDP) in Q1 2026; the 2025 deficit was 2.4% of GDP against 2.8% in 2024. In 2025 a £221bn goods deficit was partly offset by a £203bn services surplus.', 10, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'What causes a current account deficit, and what policies can correct one?', 'Cyclical causes: strong domestic growth pulling in imports; recession in export markets; a temporarily strong exchange rate; a spike in world commodity prices. Structural causes: low productivity and high relative unit labour costs; weak non-price competitiveness; deindustrialisation; low investment; North Sea depletion; foreign ownership of domestic assets weakening primary income. Policies: expenditure-reducing (contractionary fiscal/monetary policy); expenditure-switching (depreciation); protectionism (risks retaliation); supply-side policy, which tackles the structural cause but works only over many years.', 11, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Compare floating, fixed and managed exchange rate systems.', 'Floating: set purely by demand for and supply of the currency (the UK since leaving the ERM in September 1992). Gives automatic current account adjustment, needs no reserves and frees monetary policy, but is volatile and can import inflation. Fixed: the central bank defends a declared value using reserves and interest rates (Bretton Woods 1944-71). Gives certainty and inflation discipline, but needs large reserves, subordinates monetary policy and invites speculative attack. Managed (dirty) float: mostly market-determined with official intervention to smooth movements. The impossible trinity: a country can have only two of free capital movement, a fixed rate and independent monetary policy.', 12, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'State the Marshall-Lerner condition and explain competitive devaluation.', 'Marshall-Lerner: a depreciation improves the current account only if PED(exports) + PED(imports) > 1. If the sum is below 1, demand is inelastic, import volumes barely fall while each import costs more, and the balance worsens. Competitive devaluation is a deliberate reduction in the exchange rate to gain a trade advantage; it is a beggar-my-neighbour policy that works only if partners do not retaliate. If several devalue together, relative rates are unchanged, nothing is gained and global inflation rises, as in the 1930s.', 13, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'Explain the J-curve effect.', 'After a depreciation the current account first worsens and only later improves. Immediately, import prices in sterling rise while contracted volumes are unchanged, so the import bill rises: short-run elasticities are low and Marshall-Lerner is not met. Over time foreign buyers switch to cheaper exports, domestic buyers substitute away from dearer imports and exporters add capacity, so elasticities rise, Marshall-Lerner is satisfied and the balance improves. <svg viewBox="0 0 220 150" width="220" height="150" style="display:block;margin:6px auto"><line x1="30" y1="130" x2="205" y2="130" stroke="#0B1E3F"/><line x1="30" y1="130" x2="30" y2="20" stroke="#0B1E3F"/><line x1="30" y1="75" x2="200" y2="75" stroke="#0B1E3F" stroke-width="0.6" stroke-dasharray="3 2"/><line x1="60" y1="28" x2="60" y2="130" stroke="#0B1E3F" stroke-width="0.6" stroke-dasharray="3 2"/><path d="M45 75 L60 75 C72 95 85 108 98 110 C118 113 135 98 148 75 C162 50 180 38 198 32" fill="none" stroke="#0B1E3F" stroke-width="1.8"/><text x="28" y="78" font-size="8" fill="#0B1E3F" text-anchor="end">0</text><text x="63" y="25" font-size="7" fill="#0B1E3F">depreciation</text><text x="28" y="18" font-size="8" fill="#0B1E3F" text-anchor="end">CA</text><text x="205" y="145" font-size="8" fill="#0B1E3F" text-anchor="end">Time</text></svg>', 14, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'List the stages of economic integration and distinguish trade creation from trade diversion.', 'Free trade area (no internal tariffs, separate external tariffs, so rules of origin are needed); customs union (adds a common external tariff); single market (adds free movement of goods, services, capital and labour plus harmonised regulation); monetary union (adds a single currency and central bank); full economic union (adds fiscal harmonisation). Trade creation: production shifts from a higher-cost domestic producer to a lower-cost partner, raising welfare. Trade diversion: the common external tariff shifts production from a lower-cost non-member to a higher-cost member, lowering welfare. A union is beneficial overall only if creation exceeds diversion.', 15, 'alevel'),
  ('Economics', 'AQA', '3.2.6', 'The International Economy', 'How is development measured, and what are the main barriers and strategies?', 'Measures: real GNI per capita (PPP); the HDI (life expectancy, education, GNI per capita, scored 0-1); the Multidimensional Poverty Index; single indicators such as infant mortality, literacy, access to clean water and the Gini coefficient. Barriers: the savings gap; poor infrastructure; weak human capital; primary product dependency (volatile prices, Prebisch-Singer, the resource curse); weak institutions and corruption; debt burden; capital flight and brain drain; rapid population growth; rich-country trade barriers and tariff escalation. Strategies: trade liberalisation and export-led growth; attracting FDI; investment in human capital and infrastructure; aid; debt relief; microfinance; industrial policy and diversification; institutional reform.', 16, 'alevel');
